<?php
declare(strict_types=1);
if (getenv('COUPONHUB_RUN_DB_TEST') !== '1') exit('SKIP: isolated DB opt-in required');
require __DIR__.'/../app/bootstrap.php';
use App\Core\{Auth,Database,Session};
use App\Repositories\{AdminRepository,ArticleRepository,CampaignRepository,MerchantAccessRepository,OAuthRepository,UserRepository};
ob_start(); session_save_path(sys_get_temp_dir());
function fourthCheck(bool $ok,string $label): void {if (!$ok) throw new RuntimeException('FAIL: '.$label);echo 'PASS: '.$label."\n";}
function fourthReject(callable $call,string $label): void {try {$call();} catch (RuntimeException $e) {fourthCheck(true,$label);return;} throw new RuntimeException('FAIL: accepted '.$label);}
$db=Database::connection();
fourthCheck((int)$db->query('SELECT @@port')->fetchColumn()===13379 && $db->query('SELECT DATABASE()')->fetchColumn()==='couponhub_merge_test','isolated DB required');
$users=new UserRepository($db);$repo=new AdminRepository($db);$oauth=new OAuthRepository($db);
$admin=$users->findByLogin('admin_demo');$user=$users->findByLogin('user_demo');$shopper=$users->findByLogin('merchant_shops');
$aid=(int)$admin['id'];$uid=(int)$user['id'];$mid=(int)$shopper['id'];
Auth::login($user);$version=(int)$user['auth_version'];
fourthReject(fn()=>$repo->setUserStatus($uid,$aid,'LOCKED'),'ordinary User cannot lock Admin through repository');
fourthReject(fn()=>$repo->setUserStatus($aid,$aid,'LOCKED'),'Admin cannot lock self');
$repo->setUserStatus($aid,$uid,'LOCKED');$repo->setUserStatus($aid,$uid,'ACTIVE');
fourthCheck(Auth::user()===null,'old User session remains invalid after lock then unlock without intervening request');
fourthCheck((int)$users->findById($uid)['auth_version']===$version+2,'both state transitions invalidate existing sessions');
fourthCheck((int)$db->query("SELECT COUNT(*) FROM activity_logs WHERE action='USER_STATUS'")->fetchColumn()===2,'User status audit persisted');
$category=(int)$db->query('SELECT id FROM categories ORDER BY id LIMIT 1')->fetchColumn();
fourthReject(fn()=>$repo->toggleCategory($category,false,$uid),'category toggle requires active Admin in transaction');
fourthReject(fn()=>$repo->toggleCategory($category,false),'missing actor cannot toggle category');
$repo->toggleCategory($category,false,$aid);$repo->toggleCategory($category,true,$aid);
fourthCheck((int)$db->query("SELECT COUNT(*) FROM activity_logs WHERE action='CATEGORY_STATUS'")->fetchColumn()===2,'category changes audited');
$articles=new ArticleRepository($db);$values=['title'=>'Phase 4 acceptance','body'=>'Safe plain text body','status'=>'DRAFT'];
fourthReject(fn()=>$articles->save($uid,null,$values),'ordinary User cannot write article directly');
$article=$articles->save($aid,null,$values);$articles->save($aid,$article,$values+['summary'=>'updated']);
fourthCheck((int)$db->query("SELECT COUNT(*) FROM activity_logs WHERE action='ARTICLE_SAVE'")->fetchColumn()===2,'article insert and update audited');
$articles->save($aid,$article,array_replace($values,['status'=>'PUBLISHED']));
$published=$articles->find($article)['published_at'];
fourthCheck($published!==null,'publishing sets timestamp without prepared-parameter collation conflict');
$articles->save($aid,$article,array_replace($values,['status'=>'PUBLISHED','body'=>'Changed published content']));
fourthCheck($articles->find($article)['published_at']===$published,'published edit preserves first publication time');
$articles->save($aid,$article,array_replace($values,['status'=>'ARCHIVED']));
fourthCheck($articles->find($article)['published_at']===null && $articles->published()===[],'archived article disappears from public list');
$campaigns=new CampaignRepository($db);$campaign=(int)$db->query('SELECT id FROM campaigns ORDER BY id LIMIT 1')->fetchColumn();
$pivot=$db->query('SELECT campaign_id,coupon_id FROM campaign_coupons ORDER BY campaign_id,coupon_id LIMIT 1')->fetch();
fourthReject(fn()=>$campaigns->detachAdmin((int)$pivot['campaign_id'],(int)$pivot['coupon_id'],$uid),'User cannot detach Admin campaign relation');
fourthReject(fn()=>$campaigns->detachAdmin((int)$pivot['campaign_id'],(int)$pivot['coupon_id']),'missing actor cannot detach Admin campaign relation');
$count=(int)$db->query('SELECT COUNT(*) FROM campaign_coupons')->fetchColumn();
$campaigns->detachAdmin((int)$pivot['campaign_id'],(int)$pivot['coupon_id'],$aid);
fourthCheck((int)$db->query('SELECT COUNT(*) FROM campaign_coupons')->fetchColumn()===$count-1,'Admin detach removes only intended relation');
$campaigns->attach($aid,(int)$pivot['campaign_id'],(int)$pivot['coupon_id']);
$access=new MerchantAccessRepository($db);
$membership=$db->query("SELECT user_id,merchant_id FROM merchant_memberships WHERE status='ACTIVE' LIMIT 1")->fetch();
fourthReject(fn()=>$access->revoke($uid,(int)$membership['user_id'],(int)$membership['merchant_id'],'Attempt with wrong role'),'User cannot revoke shop membership at repository');
$facebook=['provider'=>'facebook','subject'=>'100000-phase4','email'=>null,'email_verified'=>false,'name'=>'Facebook User'];
fourthReject(fn()=>$oauth->resolve($facebook),'unlinked Facebook cannot create account with unverified email');
$current=$users->findById($uid);$linked=$oauth->resolve($facebook,$current);
fourthCheck((int)$linked['id']===$uid && (int)$oauth->resolve($facebook)['id']===$uid,'Facebook explicit link followed by identity-only login');
$read=$db->prepare("SELECT provider_email,email_verified FROM oauth_accounts WHERE user_id=? AND provider='facebook'");$read->execute([$uid]);$row=$read->fetch();
fourthCheck($row['provider_email']===null && (int)$row['email_verified']===0,'no fabricated Facebook email/verified flag');
fourthReject(fn()=>$oauth->resolve($facebook,$admin),'linked Facebook identity cannot be stolen by another account');
$other=$facebook;$other['subject']='other-facebook-identity';
fourthReject(fn()=>$oauth->resolve($other,$current),'second Facebook identity cannot replace existing provider link');
$interactions=new \App\Repositories\InteractionRepository($db);
$activeCoupon=(int)$db->query("SELECT id FROM v_coupon_status WHERE effective_status='ACTIVE' ORDER BY id LIMIT 1")->fetchColumn();
$comment=$interactions->addComment($uid,$activeCoupon,'Phase 4 visible comment');
fourthCheck(in_array((int)$comment['id'],array_map('intval',array_column($interactions->comments($activeCoupon),'id')),true),'visible comment is returned');
$db->prepare("UPDATE comments SET status='HIDDEN' WHERE id=?")->execute([(int)$comment['id']]);
fourthCheck(!in_array((int)$comment['id'],array_map('intval',array_column($interactions->comments($activeCoupon),'id')),true),'HIDDEN comment is never returned to public display');
$repo->setUserStatus($aid,$uid,'LOCKED');
fourthReject(fn()=>$oauth->resolve($facebook),'locked linked user cannot OAuth login');
$repo->setUserStatus($aid,$uid,'ACTIVE');
// Stale caller arguments do not bypass fresh repository authorization.
$db->prepare("UPDATE users SET role='USER' WHERE id=?")->execute([$aid]);
fourthReject(fn()=>$repo->setUserStatus($aid,$uid,'LOCKED'),'demoted Admin cannot change User state');
fourthReject(fn()=>$repo->toggleCategory($category,false,$aid),'demoted Admin cannot toggle category');
fourthReject(fn()=>$articles->save($aid,$article,$values),'demoted Admin cannot edit article');
fourthReject(fn()=>$campaigns->detachAdmin((int)$pivot['campaign_id'],(int)$pivot['coupon_id'],$aid),'demoted Admin cannot detach coupon');
fourthReject(fn()=>$access->revoke($aid,(int)$membership['user_id'],(int)$membership['merchant_id'],'Stale Admin request'),'demoted Admin cannot revoke membership');
$db->prepare("UPDATE users SET role='ADMIN' WHERE id=?")->execute([$aid]);
fourthCheck((int)$db->query('SELECT COUNT(*) FROM campaign_coupons')->fetchColumn()===$count,'rejected writes leave pivots intact');
Session::logout();
echo "PASS: phase 4 database acceptance. Fixture will be restored by runner.\n";
